import 'package:isar_community/isar.dart';

import '../../../../l10n/l10n.dart';

part 'address.g.dart';

@Collection(accessor: "addresses")
class Address {
  Address({
    required this.walletId,
    required this.value,
    required this.publicKey,
    required this.derivationIndex,
    required this.derivationPath,
    required this.type,
    required this.subType,
    this.otherData,
  });

  Id id = Isar.autoIncrement;

  @Index()
  late final String walletId;

  @Index(unique: true, composite: [CompositeIndex("walletId")])
  late final String value;

  late final List<byte> publicKey;

  @Index()
  late final int derivationIndex; // -1 generally means unknown

  @enumerated
  late final AddressType type;

  @enumerated
  late final AddressSubType subType;

  late final DerivationPath? derivationPath;

  late final String? otherData;

  Address copyWith({
    String? walletId,
    String? value,
    List<byte>? publicKey,
    int? derivationIndex,
    AddressType? type,
    AddressSubType? subType,
    DerivationPath? derivationPath,
    String? otherData,
  }) {
    return Address(
      walletId: walletId ?? this.walletId,
      value: value ?? this.value,
      publicKey: publicKey ?? this.publicKey,
      derivationIndex: derivationIndex ?? this.derivationIndex,
      type: type ?? this.type,
      subType: subType ?? this.subType,
      derivationPath: derivationPath ?? this.derivationPath,
      otherData: otherData ?? this.otherData,
    );
  }

  @override
  String toString() =>
      "{ "
      "id: $id, "
      "walletId: $walletId, "
      "value: $value, "
      "publicKey: $publicKey, "
      "derivationIndex: $derivationIndex, "
      "type: ${type.name}, "
      "subType: ${subType.name}, "
      "derivationPath: $derivationPath, "
      "otherData: $otherData, "
      "}";
}

// Stored by index: the values of other coins only keep the indexes of the
// ones PIVXie uses. Append new values, never insert or remove.
enum AddressType {
  p2pkh,
  p2sh,
  p2wpkh,
  cryptonote,
  mimbleWimble,
  unknown,
  nonWallet,
  ethereum,
  nano,
  banano,
  spark,
  stellar,
  tezos,
  frostMS,
  p2tr,
  solana,
  cardanoShelley,
  xelis,
  fact0rn,
  mweb,
  pivxShield;

  String get readableName => switch (this) {
    AddressType.p2pkh => "P2PKH",
    AddressType.pivxShield => l10n.coinControlShield,
    AddressType.nonWallet => l10n.addressNonWallet,
    _ => l10n.commonUnknown,
  };
}

// Stored by index, like [AddressType].
enum AddressSubType {
  receiving,
  change,
  paynymNotification,
  paynymSend,
  paynymReceive,
  unknown,
  nonWallet;

  String get prettyName => switch (this) {
    AddressSubType.receiving => l10n.addressReceiving,
    AddressSubType.change => l10n.txChange,
    AddressSubType.nonWallet => l10n.addressNonWallet,
    _ => l10n.commonUnknown,
  };
}

@Embedded(inheritance: false)
class DerivationPath {
  late final String value;

  @override
  toString() => value;

  @override
  bool operator ==(Object other) =>
      identical(this, other) || other is DerivationPath && value == other.value;

  @ignore
  @override
  int get hashCode => value.hashCode;
}
